\u4e49\u4e3a **\u4e0d\u533a\u5206\u5927\u5c0f\u5199\u7684\u5b57\u6bcd\u987a\u5e8f**\uff08`sorted(words, key=str.casefold)`\uff09\uff0c\u7b26\u5408\u666e\u901a\u8bfb\u8005\u5bf9 \u201calphabetical\u201d \u7684\u76f4\u89c9\uff1b\u540c\u65f6\u628a\u533a\u5206\u5927\u5c0f\u5199\u7684 `sorted(words)` \u4f5c\u4e3a**\u5907\u9009/\u53ef\u914d\u7f6e\u884c\u4e3a**\uff08\u901a\u8fc7 CLI \u6807\u5fd7 `--case-sensitive` \u6216\u51fd\u6570\u53c2\u6570 `case_sensitive=False` \u5207\u6362\uff09\uff0c\u5e76\u5728\u9a8c\u8bc1\u7528\u4f8b\u4e2d\u5206\u522b\u7ed9\u51fa\u4e24\u79cd\u7b56\u7565\u7684\u9884\u671f\u7ed3\u679c\u3002\n\n## 2. \u6570\u636e\u7ed3\u6784\u4e0e\u51fd\u6570\n\u7eaf Python \u6807\u51c6\u5e93\u5b9e\u73b0\uff0c\u65e0\u7b2c\u4e09\u65b9\u4f9d\u8d56\u3002\n\n```python\nimport sys\n\ndef sort_words(words, case_sensitive=False):\n    \"\"\"\u8fd4\u56de\u6309\u5b57\u6bcd\u987a\u5e8f\u6392\u5e8f\u540e\u7684\u5355\u884c\u7a7a\u683c\u5206\u9694\u6587\u672c\uff08\u65e0\u9996\u5c3e\u7a7a\u767d\uff09\u3002\n    words: \u53ef\u8fed\u4ee3\u7684 str \u5217\u8868\u3002\n    case_sensitive: False\uff08\u9ed8\u8ba4\uff0c\u4e0d\u533a\u5206\u5927\u5c0f\u5199\uff09| True\uff08\u533a\u5206\u5927\u5c0f\u5199\uff09\u3002\n    \u7a7a\u5217\u8868\u8fd4\u56de\u7a7a\u5b57\u7b26\u4e32 ''\u3002\u91cd\u590d\u5355\u8bcd\u4fdd\u7559\u4e0d\u53bb\u91cd\u3002\n    \"\"\"\n    key = None if case_sensitive else str.casefold\n    return \" \".join(sorted(words, key=key))\n\ndef sort_from_stdin(case_sensitive=False):\n    data = sys.stdin.read()\n    words = data.split()          # \u6298\u53e0\u7a7a\u683c/Tab/\u6362\u884c\n    return sort_words(words, case_sensitive)\n\ndef sort_from_args(args, case_sensitive=False):\n    return sort_words(list(args), case_sensitive)\n```\n\n- \u4e09\u4e2a\u5165\u53e3\uff1a`sort_words(words)`\uff08\u5185\u90e8\u51fd\u6570\uff09\u3001`sort_from_stdin()`\uff08stdin \u7a7a\u767d\u62c6\u5206\uff09\u3001`sort_from_args(args)`/CLI\uff08\u547d\u4ee4\u884c\u53c2\u6570\uff09\uff1b\u6240\u6709\u5165\u53e3\u5171\u7528\u540c\u4e00\u6838\u5fc3 `sort_words`\uff0c\u8f93\u51fa\u683c\u5f0f\u7edf\u4e00\u3002\n- \u8f93\u51fa\u683c\u5f0f\uff1a\u5355\u884c\u3001`' '` \u5206\u9694\u3001\u65e0\u9996\u5c3e\u7a7a\u767d\uff1b\u7a7a\u8f93\u5165 \u2192 \u8f93\u51fa\u7a7a\u5b57\u7b26\u4e32 `''`\uff08\u4e0d\u6253\u5370\u989d\u5916\u5185\u5bb9\uff09\u3002\n- CLI \u7528\u6cd5\u793a\u4f8b\uff1a`python word_sorter.py < words.txt`\uff1b`python word_sorter.py --case-sensitive banana Apple`\u3002\n\n## 3. \u6838\u5fc3\u4e0e\u5907\u9009\u6392\u5e8f\u7b56\u7565\u53ca\u9009\u62e9\u7406\u7531\n| \u7b56\u7565 | \u5b9e\u73b0 | \u7406\u7531 |\n|---|---|---|\n| \u6838\u5fc3\uff08\u9ed8\u8ba4\uff0c\u4e0d\u533a\u5206\u5927\u5c0f\u5199\uff09 | `sorted(words, key=str.casefold)` | casefold \u5bf9\u5927\u5c0f\u5199\u6298\u53e0\u66f4\u5f3a\uff08\u542b \u00df\u2192ss \u7b49\uff09\uff0c\u6700\u8d34\u5408\u201c\u5b57\u5178\u5e8f\u201d\u76f4\u89c9\uff1b\u7a33\u5b9a\u3001O(n log n)\u3001\u7eaf\u6807\u51c6\u5e93 |\n| \u5907\u9009\uff08\u533a\u5206\u5927\u5c0f\u5199\uff09 | `sorted(words)` \u5373 `key=None` | \u5b8c\u5168\u4fdd\u7559\u7801\u70b9\u987a\u5e8f\uff08\u5927\u5199\u5b57\u6bcd\u5148\u4e8e\u5c0f\u5199\uff09\uff0c\u4f5c\u4e3a\u53ef\u914d\u7f6e\u5907\u9009\uff1b\u4fbf\u4e8e\u5bf9\u7167\u5dee\u5f02 |\n- \u9009\u62e9\u7406\u7531\uff1a\u4efb\u52a1\u6587\u672c\u4f7f\u7528 \u201calphabetically\u201d\uff0c\u666e\u901a\u8bfb\u8005\u9884\u671f\u5ffd\u7565\u5927\u5c0f\u5199\uff1b\u5907\u9009\u4fdd\u7559\u4ee5\u6ee1\u8db3\u4e25\u683c\u7801\u70b9\u8bed\u4e49\u3002\n\n## 4. \u63a7\u5236\u4e0e\u5bf9\u7167\uff08\u5bf9\u7167\u7ec4\u8bbe\u8ba1\uff0c\u4fdd\u8bc1\u53ef\u590d\u73b0\u53ef\u590d\u6838\uff09\n\u4e3a\u540c\u4e00\u7ec4\u6570\u636e\u5728\u4e24\u79cd\u7b56\u7565\u4e0b\u5404\u7ed9\u9884\u671f\u8f93\u51fa\uff0c\u5e76\u8bbe\u8ba1\u4ee5\u4e0b\u5bf9\u7167\u7ef4\u5ea6\uff1a\n- **\u5927\u5c0f\u5199\u654f\u611f vs \u4e0d\u654f\u611f**\uff1a\u540c\u4e00\u8f93\u5165\uff08`banana, apple, Cherry, apple`\uff09\u5728\u4e24\u79cd\u7b56\u7565\u4e0b\u7684\u8f93\u51fa\uff1b\u9884\u671f\u5dee\u5f02\uff1a\u4e0d\u654f\u611f \u2192 `apple apple banana Cherry`\uff1b\u654f\u611f \u2192 `Cherry apple apple banana`\uff08\u2018Cherry\u2019 \u56e0\u5927\u5199 C \u7801\u70b9(67)\u5c0f\u4e8e\u5c0f\u5199 a(97) \u800c\u6392\u524d\uff09\u3002\n- **\u6df7\u5408\u5927\u5c0f\u5199**\uff1a`Apple, apple, APPLE` \u9a8c\u8bc1 casefold \u5e73\u5c40\u65f6\u7a33\u5b9a\u6392\u5e8f\u4fdd\u6301\u539f\u59cb\u76f8\u5bf9\u987a\u5e8f\u3002\n- **\u540c\u8bcd\u91cd\u590d**\uff1a\u4fdd\u7559\u5168\u90e8\u91cd\u590d\uff0c\u76f8\u540c\u8bcd\u5728\u5e73\u5c40\u952e\u4e0b\u76f8\u90bb\u3002\n- **\u7a7a\u8f93\u5165**\uff1a\u8f93\u51fa\u7a7a\u5b57\u7b26\u4e32\u3002\n- **\u591a\u7a7a\u767d\u6298\u53e0**\uff1a\u591a\u4e2a\u7a7a\u683c/Tab/\u6362\u884c\u5747\u6298\u53e0\u4e3a\u5355\u4e00\u7a7a\u683c\u3002\n- **\u975e\u82f1\u6587**\uff1a\u897f\u91cc\u5c14/\u5e0c\u814a\uff08\u03b1 \u03b2 \u0393 \u03b3\uff09\u4e0e\u6ce8\u97f3\u7b26\u53f7\uff08\u3105\u3106\u3107\u3108\uff09\u6309 Unicode \u7801\u70b9\u5347\u5e8f\u3001\u4e0d\u505a locale \u6392\u5e8f\u3002\n\n## 5. \u9a8c\u8bc1\u65b9\u6848\n\u4e3a\u4fbf\u4e8e\u88c1\u5224\u590d\u6838\uff0c\u5217\u51fa**\u5355\u5143\u7528\u4f8b\u8868**\u3001**\u8fb9\u754c\u7528\u4f8b\u8868**\u4e0e**\u9884\u671f\u8f93\u51fa**\uff08\u5747\u5df2\u7528 Python 3.14 \u63a2\u6d4b\u6838\u5b9e\uff0c\u4f46\u5c5e\u201c\u8bbe\u8ba1\u9884\u671f\u201d\uff0c\u975e\u201c\u5df2\u8fd0\u884c\u5b9e\u9a8c\u201d\uff09\uff1a\n\n### \u5355\u5143\u7528\u4f8b\u8868\n| \u7f16\u53f7 | \u8f93\u5165 (list/str) | \u7b56\u7565 | \u9884\u671f\u8f93\u51fa |\n|---|---|---|---|\n| U1 | `[\"banana\",\"apple\",\"Cherry\",\"apple\"]` | ci(\u9ed8\u8ba4) | `apple apple banana Cherry` |\n| U1b | \u540c\u4e0a | cs(\u5907\u9009) | `Cherry apple apple banana` |\n| U2 | `[\"Apple\",\"apple\",\"APPLE\",\"Banana\",\"banana\"]` | ci | `Apple apple APPLE Banana banana`\uff08\u5e73\u5c40\u7a33\u5b9a\u5e8f\uff09 |\n| U2b | \u540c\u4e0a | cs | `APPLE Apple Banana apple banana` |\n| U3 | `[\"zebra\",\"Apple\",\"Mango\",\"apple\",\"banana\"]` | ci | `Apple apple banana Mango zebra` |\n| U4 | \u8c03\u7528 `sort_words([])` | ci/cs | `''`\uff08\u7a7a\u5b57\u7b26\u4e32\uff09 |\n| U5 | \u8c03\u7528 `sort_from_args([\"b\",\"a\",\"c\"])` | ci | `a b c` |\n\n### \u8fb9\u754c\u7528\u4f8b\u8868\n| \u7f16\u53f7 | \u8f93\u5165 | \u9884\u671f\u884c\u4e3a |\n|---|---|---|\n| B1 \u91cd\u590d\u8bcd | `[\"go\",\"go\",\"Go\",\"to\",\"TO\",\"to\"]` ci | `go go Go to TO to`\uff08\u4e0d\u53bb\u91cd\u3001\u5e73\u5c40\u7a33\u5b9a\uff09 |\n| B2 \u591a\u7a7a\u767d/\u6362\u884c | `\"a  c\\nb\\t b a\"` \u7ecf stdin \u62c6\u5206 | `a a b b c` |\n| B3 \u7a7a stdin | \u7a7a\u8f93\u5165 | `''`\uff08\u7a7a\u5b57\u7b26\u4e32\u8f93\u51fa\uff09 |\n| B4 \u5e0c\u814a/\u897f\u91cc\u5c14 | `[\"\u03b2\",\"\u03b1\",\"\u0393\",\"\u03b3\",\"\u0391\"]` ci | `\u03b1 \u0391 \u03b2 \u0393 \u03b3`\uff08\u7801\u70b9\u5347\u5e8f\u3001\u4e0d locale\uff09 |\n| B4b \u540c\u4e0a | cs | `\u0391 \u0393 \u03b1 \u03b2 \u03b3` |\n| B5 \u6ce8\u97f3 | `[\"\u3105\",\"\u3106\",\"\u3107\",\"\u3108\"]` | `\u3105 \u3106 \u3107 \u3108`\uff08\u7801\u70b9\u5347\u5e8f\uff09 |\n| B6 \u4e13\u6709\u540d\u8bcd | `[\"paris\",\"Paris\",\"PARIS\"]` ci | \u4e09\u8005\u540c\u4e00 casefold \u952e\uff0c\u7a33\u5b9a\u6392\u5e8f\u4fdd\u6301\u8f93\u5165\u76f8\u5bf9\u987a\u5e8f \u2192 `paris Paris PARIS` |\n\n### \u9a8c\u8bc1 / \u9a8c\u6536\u6267\u884c\u6b65\u9aa4\uff08\u53ef\u4ea4\u4ed8\u3001\u53ef\u590d\u73b0\u3001\u53ef\u7531\u88c1\u5224\u590d\u6838\uff09\n1. \u5c06\u4e0a\u8ff0 U/B \u7528\u4f8b\u5199\u6210 `test_word_sorter.py`\uff08\u6807\u51c6\u5e93 `unittest` \u6216\u7b80\u5355\u65ad\u8a00\u811a\u672c\uff09\uff0c\u65ad\u8a00 `sort_words`\u3001`sort_from_stdin`\u3001`sort_from_args` \u8f93\u51fa\u4e0e\u9884\u671f\u8868\u9010\u6761\u76f8\u7b49\uff08\u542b `repr` \u5bf9\u6bd4\u4ee5\u6355\u83b7\u5c3e\u968f\u7a7a\u767d/\u6362\u884c\u5dee\u5f02\uff09\u3002\n2. `python3 test_word_sorter.py` \u5168\u7eff\uff1b\u540c\u65f6\u8dd1 `python3 -m py_compile word_sorter.py` \u4e0e `python3 word_sorter.py - < sample.txt` \u5192\u70df\u9a8c\u8bc1 CLI\uff08sample.txt \u7528\u591a\u7a7a\u767d+\u6362\u884c\u6837\u4f8b\uff09\u3002\n3. \u9a8c\u6536\u6807\u51c6\uff1a\n - \u8f93\u51fa\u6052\u4e3a**\u5355\u884c**\u3001\u5355\u8bcd\u4ee5**\u5355\u4e2a\u7a7a\u683c**\u5206\u9694\u3001**\u65e0\u9996\u5c3e\u7a7a\u767d**\uff08\u542b\u4e0d\u53ef\u89c1\u7a7a\u767d\uff0c\u7528 `repr()` \u590d\u6838\uff09\uff1b\n - \u7a7a\u8f93\u5165 \u2192 \u51c6\u786e\u8f93\u51fa\u7a7a\u5b57\u7b26\u4e32\uff1b\n - \u91cd\u590d\u5355\u8bcd\u5168\u90e8\u4fdd\u7559\u3001\u4e0d\u53bb\u91cd\uff1b\n - \u9ed8\u8ba4\u4e0d\u533a\u5206\u5927\u5c0f\u5199\uff08casefold\uff09\u884c\u4e3a\u4e0e\u8868 U1/U2 \u4e00\u81f4\uff0c\u5f00\u542f `--case-sensitive` \u540e\u4e0e U1b/U2b \u4e00\u81f4\uff1b\n - \u975e\u82f1\u6587\u6309 Unicode \u7801\u70b9\u5347\u5e8f\uff0c\u65e0 locale \u4f9d\u8d56\uff1b\n - \u4ee3\u7801\u4ec5\u4f9d\u8d56 Python \u6807\u51c6\u5e93\u3002\n\n## 6. \u53ef\u884c\u6027\u8bc4\u4f30\n- \u4ec5\u7528\u6807\u51c6\u5e93\uff08`sorted`\u3001`str.casefold`\u3001`sys.stdin`\uff09\uff0c\u65e0\u9700\u5b89\u88c5\u4f9d\u8d56\u3001\u65e0\u9700\u8ba1\u7b97/\u7f51\u7edc\u8d44\u6e90\uff0c\u5355\u6587\u4ef6 (~30 \u884c) \u53ef\u5b9e\u73b0\u3002\n- \u672c\u4efb\u52a1\u4e3a\u8bbe\u8ba1\u7c7b\uff08track.md \u6ce8\u660e \u201crepositories and compute are not required\u201d\uff09\uff0c\u8bbe\u8ba1\u5b8c\u6574\u3001\u9884\u671f\u8f93\u51fa\u5747\u5df2\u9884\u6838\u5b9e\uff0c\u4ea4\u4ed8\u540e\u53ef\u6309\u4e0a\u8ff0\u6b65\u9aa4\u76f4\u63a5\u8fd0\u884c\u9a8c\u8bc1\uff0c\u65e0\u9700\u771f\u5b9e\u5b9e\u9a8c\u6267\u884c\u3002", "evidence": "/workspace \u4ec5\u542b task.json\uff0c\u65e0\u6837\u4f8b\u6570\u636e/\u73b0\u6210\u4ee3\u7801\uff1b\u73af\u5883 Python 3.14.4\uff0cstdin/sorted/casefold \u53ef\u7528\u3002\u6240\u6709\u9884\u671f\u8f93\u51fa\u5df2\u7528 Python \u5b9e\u9645\u63a2\u6d4b\u6838\u5b9e\uff1aci: [\"banana